import org.audiveris.omr.sheet.Book;
import java.nio.file.*;import java.util.*;
public class RealFlagCompetitionManualImageProbe extends RealLedgerMembershipImageProbe {
 private final Object actual;
 static final List<Object[]> declared=new ArrayList<>();
 static String declarations()throws Exception {List<String> rows=new ArrayList<>();int i=0;for(Object[] d:declared)rows.add("{\"relation_identity_label\":"+(++i)+",\"manual\":"+call(d[0],"isManual")+",\"present\":"+call(d[1],"containsEdge",d[0])+",\"source_removed\":"+call(d[2],"isRemoved")+",\"target_removed\":"+call(d[3],"isRemoved")+"}");return "["+String.join(",",rows)+"]";}
 public RealFlagCompetitionManualImageProbe(Book book,SortedSet<Integer> ids){super(book,ids);actual=book;}
 static String flags(Object sheet)throws Exception {
 List<String> systems=new ArrayList<>();for(Object sys:(List<?>)call(sheet,"getSystems")){
 Object sig=call(sys,"getSig");List<String> flags=new ArrayList<>(),relations=new ArrayList<>();
 for(Object v:(Collection<?>)call(sig,"vertexSet"))if(v.getClass().getSimpleName().equals("FlagInter"))flags.add("{\"id\":"+call(v,"getId")+",\"bounds\":"+rect(call(v,"getBounds"))+",\"shape\":\""+call(v,"getShape")+"\",\"grade\":"+call(v,"getGrade")+",\"contextual_grade\":"+call(v,"getContextualGrade")+",\"glyph\":"+glyph(call(v,"getGlyph"))+"}");
 for(Object e:(Collection<?>)call(sig,"edgeSet")){String name=e.getClass().getSimpleName();if(name.equals("FlagStemRelation")||name.equals("Exclusion")){Object a=call(sig,"getEdgeSource",e),b=call(sig,"getEdgeTarget",e);if(a.getClass().getSimpleName().equals("FlagInter")||b.getClass().getSimpleName().equals("FlagInter"))relations.add("{\"kind\":\""+name+"\",\"source_kind\":\""+a.getClass().getSimpleName()+"\",\"source_bounds\":"+rect(call(a,"getBounds"))+",\"target_kind\":\""+b.getClass().getSimpleName()+"\",\"target_bounds\":"+rect(call(b,"getBounds"))+"}");}}
 systems.add("{\"system\":"+call(sys,"getId")+",\"flags\":["+String.join(",",flags)+"],\"relations\":["+String.join(",",relations)+"]}");}return "["+String.join(",",systems)+"]";
 }
 public void process(){try {Object stub=((List<?>)call(actual,"getStubs")).get(0);List<String> stages=new ArrayList<>();for(String name:new String[]{"SYMBOLS","WEAK_PURGED","FLAG_OVERLAPS","MANUAL_DECLARED","FLAG_EXCLUSIONS_REDUCED","LINKS"}){if(name.equals("SYMBOLS")||name.equals("LINKS"))call(stub,"reachStep",c("step.OmrStep").getField(name).get(null),false);Object sheet=call(stub,"getSheet");if(name.equals("SYMBOLS"))for(Object sys:(List<?>)call(sheet,"getSystems"))call(call(sys,"getSig"),"contextualize");if(name.equals("WEAK_PURGED"))for(Object sys:(List<?>)call(sheet,"getSystems"))call(call(sys,"getSig"),"deleteWeakInters");
if(name.equals("FLAG_OVERLAPS"))for(Object sys:(List<?>)call(sheet,"getSystems")){Object sig=call(sys,"getSig");List<Object> flags=new ArrayList<>();for(Object v:(Collection<?>)call(sig,"vertexSet"))if(v.getClass().getSimpleName().equals("FlagInter"))flags.add(v);flags.sort((a,b)->{try{return Integer.compare(((java.awt.Rectangle)call(a,"getBounds")).x,((java.awt.Rectangle)call(b,"getBounds")).x);}catch(Exception e){throw new RuntimeException(e);}});call(make("sig.SigReducer",sys,true),"detectOverlaps",flags);}
if(name.equals("MANUAL_DECLARED"))for(Object sys:(List<?>)call(sheet,"getSystems")){Object sig=call(sys,"getSig");for(Object e:(Collection<?>)call(sig,"edgeSet"))if(e.getClass().getSimpleName().equals("Exclusion")){Object a=call(sig,"getEdgeSource",e),b=call(sig,"getEdgeTarget",e);if(a.getClass().getSimpleName().equals("FlagInter")&&b.getClass().getSimpleName().equals("FlagInter")){call(e,"setManual",true);call(a,"setManual",true);call(b,"setManual",true);declared.add(new Object[]{e,sig,a,b});}}}
if(name.equals("FLAG_EXCLUSIONS_REDUCED"))for(Object sys:(List<?>)call(sheet,"getSystems")){Object sig=call(sys,"getSig");List<Object> exclusions=new ArrayList<>();for(Object e:(Collection<?>)call(sig,"edgeSet"))if(e.getClass().getSimpleName().equals("Exclusion")&&call(sig,"getEdgeSource",e).getClass().getSimpleName().equals("FlagInter")&&call(sig,"getEdgeTarget",e).getClass().getSimpleName().equals("FlagInter"))exclusions.add(e);call(sig,"reduceExclusions",exclusions);}
stages.add("{\"stage\":\""+name+"\",\"systems\":"+flags(sheet)+",\"declared_relations\":"+declarations()+"}");}Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"scope\":\"fresh unchanged original SYMBOLS whole-SIG contextualize/deleteWeakInters, Flag-only detectOverlaps, declared manual Flag/Exclusion objects and reduceExclusions, then ordinary LINKS, actual Flag glyphs and incident relations, no native input\",\"stages\":["+String.join(",",stages)+"]}\n");}catch(Exception e){throw new RuntimeException(e);}}
}
